function familyView(s,ui){const {escape,money,profile}=ui;const button=(text,id,disabled=false)=>`<button class="outline" data-life="${id}" ${available(s,.5)||disabled?'disabled':''}>${text}</button>`;return `<div class="section-card"><h3>Брак и дети</h3>${householdView(s,ui)}<p>${s.married?'В браке':'Брак не зарегистрирован'} · детей ${s.childrenRecords.length}, несовершеннолетних ${dependants(s).length}.<br>Содержание детей ${money(childExpenses(s,profile(s)))}/год · забота ${caregivingHours(s)} ч/нед.</p><div class="button-row">${button('Зарегистрировать брак · 500 $','marry',s.married||!s.partner||s.age<18)}${button('Планировать ребёнка','planChild',!!s.familyPlan||s.age<21)}${button('Начать усыновление','adopt',!!s.familyPlan||s.age<21)}</div>${s.familyPlan?`<p>Активен план: ${s.familyPlan.type==='adopt'?'усыновление':'пополнение семьи'}. Ожидание ${s.familyPlan.attempts} г. Результат не появляется мгновенно.</p>${button('Приостановить план','cancelPlan')}`:''}${s.childrenRecords.map(c=>`<article class="section-card child-card" data-child-card="${c.id}"><div class="person-heading"><div class="mini-avatar">${personAvatar(c)}</div><div><h3>${escape(c.name)}</h3><p>${ageText(c.age)} · близость ${c.bond}/100 · доверие ${c.trust}/100</p></div></div>${peopleLifeView(s,c,ui)}${c.age>=6&&c.age<=25?`<details class="child-path" id="child-path-${c.id}"><summary>Обсудить интересы и будущее</summary><label>Направление<select class="child-advice-sector">${Object.entries(npcProfessions).map(([id,p])=>`<option value="${id}" ${c.life?.sector===id?'selected':''}>${p.name}</option>`).join('')}</select></label>${worldButton(s,'Предложить направление','household','childAdvice',String(c.id),s.household?.childAdvice[c.id]===s.age)}</details>`:''}<label>Дополнительное время: <output id="child-hours-${c.id}">${c.careHours}</output> ч/нед<input type="range" min="0" max="12" step="1" value="${c.careHours}" data-child-hours="${c.id}" ${available(s,.25)?'disabled':''}></label><small>Это время для общения сверх обязательного ухода. Отношения меняются за год; часы входят в общую нагрузку.</small><div class="button-row">${[['childTalk',c.age<3?'Побыть рядом':'Поговорить',c.talkYear,.25],['childActivity','Провести время',c.activityYear,.5],['childSupport','Поддержать',c.supportYear,.5]].map(([id,title,year,cost])=>`<button class="outline" data-child-action="${id}" data-child-id="${c.id}" ${available(s,cost)||year===s.age?'disabled':''}>${title}</button>`).join('')}</div><details class="gift-menu" id="gift-child-${c.id}"><summary>Подарить подарок</summary><label>Бюджет<select class="gift-budget" data-gift-owner="child:${c.id}">${giftBudgets.map(n=>`<option value="${n}">${money(n)} — ${giftName(n)}</option>`).join('')}</select></label><button class="outline" data-gift="normal" data-target="child:${c.id}" ${available(s,.25)||s.age<5||c.gifts.normalYear===s.age?'disabled':''}>Подарить</button><p class="gift-preview helper" data-gift-preview data-romance-preview="false"></p></details></article>`).join('')}${s.childrenRecords.length?button('Побыть с детьми','childrenTime'):''}</div>`;}
function pensionView(s,ui){if(s.age<55&&!s.pensionYears)return '';return `<div class="section-card"><h3>${s.retired?'Ты на пенсии':'Будущая пенсия'}</h3><p>Стаж ${s.pensionYears} г. · прогноз ${ui.money(pension({...s,retired:true},ui.profile(s)))}/год.<br>Выход доступен с 60 лет. Формула условная, единая для игры. При возвращении к постоянной работе выплата приостанавливается.</p><button class="outline" data-life="${s.retired?'returnWork':'retire'}" ${available(s,.5)||!s.retired&&s.age<60?'disabled':''}>${s.retired?'Вернуться к поиску работы':'Выйти на пенсию'}</button></div>`;}

const coreCourseLanguages=['en','es','it','fr','zh','ru'];
function languageCoursesView(s,ui){const {money,profile}=ui;if(s.age<6)return '<div class="section-card locked-section"><h3>Языковые курсы</h3><p>Откроется с 6 лет.</p></div>';const m=s.mobility,a=m.arrivalCourse,local=localLanguage(s.country),languages=s.country!==m.birthCountry&&!coreCourseLanguages.includes(local)?[...coreCourseLanguages,local]:coreCourseLanguages;return `<details class="section-card" id="languageCourses"><summary>Языковые курсы</summary><p>У каждого языка свой прогресс. Один курс каждого языка за год: +18 к владению, 2 ч/нед до конца года. Стоимость ${money(180*profile(s).cost)}; несовершеннолетним могут помочь родители.</p><div class="language-course-grid">${languages.map(language=>{const level=m.languages[language]||0;return `<article class="language-course"><h4>${languageNames[language]}</h4><p>${level}/100</p><div class="track"><i style="width:${level}%"></i></div><button class="outline" data-language-course="${language}" ${available(s,1)||level>=100||m.courseYears[language]===s.age?'disabled':''}>${level>=100?'Язык освоен':'Пройти курс'}</button></article>`;}).join('')}</div>${a&&a.country===s.country&&s.country!==m.birthCountry?`<section class="arrival-language"><h4>Местный язык после переезда · ${languageNames[localLanguage(s.country)]}</h4><p>Двухлетняя программа адаптации: +28 за учебный год, 4 ч/нед, ${money(220*profile(s).cost)} за год. Завершено ${a.completedYears} из 2 лет.</p><button class="outline" data-arrival-language ${available(s,.5)||a.completedYears>=2||a.lastYear===s.age||m.courseYears[a.language]===s.age||(m.languages[a.language]||0)>=100?'disabled':''}>Пройти год адаптации</button></section>`:''}</details>`;}

function educationView(s,ui){const {money,escape,profile,actionButton}=ui;const econ=profile(s),q=s.school,blocked=!!available(s,.5);const button=(text,action,value='',extra=false)=>`<button type="button" class="outline" data-education="${action}" data-value="${value}" ${blocked||extra?'disabled':''}>${text}</button>`;let html='';html+=!q.started?'<div class="section-card locked-section" aria-disabled="true"><h3>Школа</h3><p>Откроется после поступления в школу</p></div>':`<div class="info-box"><h3>Школа</h3><p>${q.completed11?'Аттестат за 11 классов':q.completed9&&!['school','upper'].includes(q.route)?'Аттестат за 9 классов':q.grade+' класс'} · учебные успехи ${s.academics}/100 · интеллект ${s.iq}/100<br>${schoolTracks[q.track].name} · регулярная учёба ${schoolHours(s)} ч/нед.</p>${actionButton('study')}</div>`;

html+=schoolClubsView(s);
html+=s.age<16||!q.completed9?'<div class="section-card locked-section" aria-disabled="true"><h3>Колледжи</h3><p>Откроется после окончания средней школы. Для поступления нужен аттестат за 9 классов.</p><p>Доступно с 16 лет.</p></div>':`<details id="collegeCatalog" class="section-card education-catalog"><summary>Колледжи</summary><p class="helper">После 9 класса. Базовый срок — 3 года. Учитываются успеваемость, профиль и конкурс; доступны три подачи документов за год. Обучение и подработка совместимы при разумной нагрузке.</p>${Object.entries(colleges).map(([id,c])=>`<div class="section-card" data-institution="${id}" data-level="college"><h3>${institutionName(s.country,'college',id)}</h3><p>${c.years} года · ${money(c.fee*econ.cost)}/год · твоя часть ${money(familyEducationFunding(s,Math.round(c.fee*econ.cost),econ).student)}</p><label>Факультет<select class="faculty-select">${c.faculties.map(f=>`<option value="${f}">${faculties[f].name} · конкурс от ${admissionAssessment(s,'college',id,f).minimum}</option>`).join('')}</select></label><p class="funding-preview" data-funding-preview></p><button type="button" class="outline" data-study-loan="college" data-institution="${id}" ${blocked||!q.completed9?'disabled':''}>Оформить учебный кредит</button><button class="outline" data-enroll="college" data-institution="${id}" ${blocked||s.age<16||!q.completed9||s.uni||s.college?'disabled':''}>Подать документы</button></div>`).join('')}</details>`;
if(q.completed11)html+=`<details id="universityCatalog" class="section-card education-catalog"><summary>Институты</summary><p class="helper">Нужен аттестат за 11 классов. После совместимого колледжа — 2 года; иначе 4 года, медицина — 6. Успехи от 40 и интеллект от 70 дают скидку 70%. Конкурс учитывает успеваемость, профильные навыки и подготовку. В пограничном случае возможен отказ; повторная подача в то же учреждение — в следующем году.</p>${Object.entries(universities).map(([id,u])=>`<div class="section-card" data-institution="${id}" data-level="university"><h3>${institutionName(s.country,'university',id)}</h3><p>Базовая оплата ${money(u.fee*econ.cost)}/год до скидки. Родители помогают в пределах бюджета и могут не поддержать выбранное направление.</p><label>Факультет<select class="faculty-select">${u.faculties.map(f=>`<option value="${f}">${faculties[f].name} · конкурс от ${admissionAssessment(s,'university',id,f).minimum}${hasCollege(s,faculties[f].field)?' · ускоренно, 2 года':''}</option>`).join('')}</select></label><p class="funding-preview" data-funding-preview></p><button type="button" class="outline" data-study-loan="university" data-institution="${id}" ${blocked||s.age<17?'disabled':''}>Оформить учебный кредит</button><button class="outline" data-enroll="university" data-institution="${id}" ${blocked||s.age<17||s.uni||s.college?'disabled':''}>Подать документы</button><small>Допуск и ускорение проверяются по выбранному факультету.</small></div>`).join('')}</details>`;else html+='<div class="section-card locked-section" aria-disabled="true"><h3>Институты</h3><p>Откроется после окончания старшей школы. Для поступления нужен аттестат об окончании школы.</p></div>';
html+=languageCoursesView(s,ui);
if(q.completed9&&!s.college&&!s.uni)html+=`<div class="section-card"><h3>Путь после 9 класса</h3><p>Колледж даёт профессию. После него совместимую программу института можно пройти за 2 года. Старшая школа открывает все факультеты. Выбор работы сохраняет возможность вернуться к обучению.</p><div class="button-row">${button('Пойти в колледж','route','college')}${button(s.age>=18?'Завершить 10–11 классы вечерне':'Продолжить 10–11 класс','route','upper',q.completed11)}${button('Начать трудовой путь','route','work')}</div></div>`;
if(s.college||s.uni){const p=s.college||s.university,funding=educationFunding(s,econ);html+=`<div class="section-card current-job"><span class="eyebrow">ТЕКУЩАЯ ПРОГРАММА</span><h3>${p.institution==='legacy'?'Ранее начатая программа':institutionName(s.country,s.college?'college':'university',p.institution)}</h3><p>Факультет: ${faculties[p.facultyId]?.name||s.degreeField}<br>Осталось ${s.college?s.college.remaining:s.uni} г.${p.accelerated?' · ускоренная программа после колледжа':''}<br>Обучение ${money(funding.total)}/год · родители ${money(funding.parents)} · банк ${money(funding.loan)} · твоя часть ${money(funding.student)}<br>При успеваемости ниже 25 учебный год не закрывается.</p>${button('Прервать обучение','pause')}</div>`;}
if(s.credentials.length)html+=`<div class="section-card"><h3>Твои дипломы</h3>${s.credentials.map(d=>`<p><b>${d.level==='college'?'Колледж':'Институт'}</b> · ${d.legacy?(degreeFields[d.field]||'Ранее полученный диплом'):faculties[d.facultyId]?.name||escape(d.field)}<br>${d.legacy?'':institutionName(s.country,d.level,d.institution)+'<br>'}Получен в ${ageText(d.age)}${d.accelerated?' · ускоренная программа':''}</p>`).join('')}</div>`;
if(s.age>=14)html+=`<div class="section-card"><h3>Подготовка к поступлению</h3><p>Один курс за год · ${money(150*econ.cost)} · +8 конкурсных баллов в этом году. До трёх заявлений в разные учреждения.</p>${button('Подготовиться','prepare','',s.energy<1||s.admissionPreparation?.age===s.age)}</div>`;
const placement=activeInternship(s);if(placement)html+=`<article class="section-card internship-card"><div class="person-heading">${companyLogo(placement)}<div><span class="eyebrow">УЧЕБНАЯ ПРАКТИКА</span><h3>${escape(placement.companyName)}</h3></div></div><p>${placement.role}<br>${placement.hours} ч/нед в составе учебного расписания · ${placement.creditedJob?'Текущая профильная работа зачтена как практика':'Наставник и отчёт; выплата учитывается за следующий год'}.</p><p class="helper">Для зачёта нужны успеваемость от 25 и нагрузка не выше 80 ч/нед. Практика повышает профильный навык и даёт опыт для резюме.</p></article>`;
if(s.practiceHistory?.length)html+=`<details class="section-card"><summary>Моя практика · ${s.practiceHistory.length}</summary>${s.practiceHistory.map(p=>`<p><b>${escape(p.companyName)}</b><br>${p.role} · зачтена</p>`).join('')}</details>`;
if(s.college||s.uni||s.credentials.length||s.studyFinance.loans.some(l=>l.principal>0))html+=`<details id="studyPayments" class="section-card"><summary>Оплата обучения и учебные кредиты</summary><p>Родители могут отказаться оплачивать направление, которое не поддерживают. Его можно обсудить с ними; согласие не гарантировано. Кредит перечисляется учебному заведению. Во время обучения и ещё 2 года после него платежей нет; затем долг выплачивается за 7 лет под 4%.</p>${s.parents.map((p,index)=>{const field=p.educationViews.opposed;return p.status!=='deceased'&&p.educationViews.strict&&!parentSupportsField(s,p,field)?`<p>${p.role}: ${escape(p.name)} не поддерживает направление «${degreeFields[field]||field}».</p>${button('Обсудить оплату','appeal',index+':'+field,s.studyFinance.appeals.some(a=>a.parent===index&&a.field===field&&a.age===s.age))}`:'';}).join('')}${s.studyFinance.loans.map(l=>`<article class="study-loan"><h4>Учебный кредит · ${faculties[l.facultyId].name}</h4><p>Задолженность ${money(l.principal)} из лимита ${money(l.limit)}<br>${l.status==='paid'?'Полностью погашен':l.graceUntil===null?'Оплата программы; платежи ещё не начались':s.age<l.graceUntil?'Отсрочка до '+l.graceUntil+' лет':'Идёт погашение · осталось '+l.remainingYears+' лет'}</p></article>`).join('')||'<p>Учебных кредитов пока нет.</p>'}<p>Платёж в следующем расчётном году: ${money(studyDebtForecast(s))}.</p></details>`;return html;}

function schoolClubsView(s){if(!schoolEnrolled(s))return !s.school.started?'<div class="section-card locked-section" aria-disabled="true"><h3>Школьные команды и клубы</h3><p>Откроется после поступления в школу.</p></div>':'';return `<details id="schoolClubs" class="section-card"><summary>Школьные команды и клубы</summary><p class="helper">Можно посещать два клуба одновременно. Навыки растут каждый год.</p>${Object.entries(clubs).map(([id,c])=>`<div class="section-card"><h3>${c.name}</h3><p>С ${c.age} до 17 лет · ${c.hours} ч/нед<br>${{football:'Спорт и профильный навык → путь к профессиональной команде',computer:'IT → заказы, тестирование и разработка',science:'Учёба и интеллект → поступление',debate:'Бизнес → переговоры и офисная карьера',theatre:'Творчество и портфолио → актёрская карьера',volunteer:'Сервис и настроение → работа с людьми'}[id]}</p><button type="button" class="outline" data-career="club" data-value="${id}" ${available(s,careerCost('club'))||s.age<c.age||s.age>=18?'disabled':''}>${s.clubs.includes(id)?'Покинуть клуб':'Вступить'}</button></div>`).join('')}</details>`;}

function creationAppearanceView(s){const labels={face:'Форма лица',eyes:'Глаза',brows:'Брови',nose:'Нос',body:'Телосложение',hair:'Причёска',beard:'Борода',clothes:'Первый образ',glasses:'Очки',hat:'Головной убор',earrings:'Серьги',necklace:'Украшение'};return `<details id="birthAppearance" class="birth-appearance"><summary>Внешность персонажа</summary><div class="creation-avatar">${avatarSvg(s,true).replaceAll('portrait-','birth-portrait-')}</div><p class="helper">Показан будущий взрослый образ. Жизнь начнётся с рождения, портрет будет взрослеть. Лицо, глаза, телосложение и цвет кожи после создания изменить нельзя.</p><fieldset class="skin-palette"><legend>Естественный оттенок кожи</legend>${skinTones.map(t=>`<button type="button" class="skin-swatch ${s.appearance.skin===t.value?'selected':''}" data-birth-skin="${t.value}" style="--skin-tone:${t.value}" aria-label="${t.name}" aria-pressed="${s.appearance.skin===t.value}"></button>`).join('')}</fieldset><div class="birth-appearance-fields">${Object.entries(labels).filter(([key])=>key!=='beard'||s.gender==='male').map(([key,label])=>`<label>${label}<select data-birth-appearance="${key}">${Object.entries(appearanceOptions[key]).filter(([value])=>styleAllowed(s.gender,key,value)).map(([value,name])=>`<option value="${value}" ${s.appearance[key]===value?'selected':''}>${name}</option>`).join('')}</select></label>`).join('')}${Object.entries(appearanceColors).filter(([key])=>key!=='skin').map(([key,label])=>`<label>${label}<input type="color" data-birth-appearance="${key}" value="${s.appearance[key]}"></label>`).join('')}</div></details>`;}

function personaView(s,section,group,ui){const {escape}=ui;const tabs=`<div class="persona-tabs" role="tablist" aria-label="Личный раздел">${[['appearance','Внешность'],['character','Характер'],['desires','Желания'],['health','Здоровье'],['achievements','Достижения'],['memories','Воспоминания']].map(([id,label])=>`<button role="tab" aria-selected="${section===id}" data-persona-tab="${id}" class="${section===id?'active':''}">${label}</button>`).join('')}</div>`;let html='';
if(section==='appearance'){group=['hair','accessories','clothes'].includes(group)?group:'hair';const fields={hair:s.gender==='male'?['hair','beard']:['hair'],accessories:['hat','glasses','earrings','necklace'],clothes:['clothes']}[group],labels={hair:'Причёска',beard:'Борода',hat:'Головной убор',glasses:'Очки',earrings:'Серьги',necklace:'Украшение',clothes:'Одежда'};html=`<div class="section-card avatar-studio"><div id="largeAvatar">${avatarSvg(s,true)}</div><p class="helper">Врождённые черты выбраны при создании. Здесь можно менять стиль: причёску, бороду, одежду и аксессуары. ${s.gender==='female'?'Женские':'Мужские'} варианты; одежда и аксессуары доступны из гардероба.</p><div class="avatar-groups">${[['hair','Волосы'],['accessories','Аксессуары'],['clothes','Одежда']].map(([id,label])=>`<button class="outline ${group===id?'active':''}" data-avatar-group="${id}">${label}</button>`).join('')}</div><button class="outline" data-open-shopping="clothing">Одежда и аксессуары в покупках</button><div class="appearance-fields">${fields.map(key=>{const entries=Object.entries(appearanceOptions[key]).filter(([value])=>styleAllowed(s.gender,key,value)||value===s.appearance[key]);return `<label>${labels[key]}<select id="appearance-${key}" data-appearance="${key}" ${key==='beard'&&s.age<14?'disabled':''}>${entries.map(([value,label])=>`<option value="${value}" ${s.appearance[key]===value?'selected':''} ${styleAllowed(s.gender,key,value)&&canWear(s,key,value)?'':'disabled'}>${label}${canWear(s,key,value)?'':' · в покупках'}</option>`).join('')}</select></label>`;}).join('')}</div><div class="appearance-colors">${Object.entries(appearanceColors).filter(([key])=>!['skin','eyeColor'].includes(key)).map(([key,label])=>`<label>${label}<input id="appearance-${key}" type="color" data-appearance="${key}" value="${s.appearance[key]}"></label>`).join('')}</div></div>`;}
if(section==='character')html=`<div class="info-box"><h3>Характер складывается из поступков</h3><p>Это склонности, а не приговор. Учёба и тренировки развивают дисциплину, знакомства — общительность, помощь — эмпатию. Черты влияют на обучение, переговоры и отношения.</p></div><div class="personality-grid">${Object.entries(personalityTraits).map(([id,name])=>`<div class="section-card"><h3>${name} <b>${s.personality[id]}/100</b></h3><div class="track"><i style="width:${s.personality[id]}%"></i></div><p>${{discipline:'Помогает поддерживать рабочие результаты и аргументировать повышение.',sociability:'Повышает вероятность успешного знакомства.',empathy:'Помогает поддерживать близких и укреплять доверие.',curiosity:'Усиливает пользу самостоятельной учёбы.',resilience:'Смягчает накопление стресса.',confidence:'Помогает проявить себя в отношениях и переговорах о спортивном контракте.'}[id]}</p></div>`).join('')}</div>`;
if(section==='achievements')html=`<div class="info-box"><h3>Твои достижения</h3><p>Открыто ${s.achievements.length} из ${achievementDefinitions.length}. Полученные награды остаются даже после смены работы или завершения карьеры.</p></div><div class="achievement-grid">${achievementDefinitions.map(a=>{const unlocked=s.achievements.find(x=>x.id===a.id);return `<article class="section-card achievement ${unlocked?'unlocked':''}"><span class="achievement-icon">${unlocked?'✦':'◇'}</span><h3>${a.name}</h3><p>${a.text}</p><small>${unlocked?'Получено в '+unlocked.age+' лет':'Пока не открыто'}</small></article>`;}).join('')}</div>`;
if(section==='memories'){const memories=s.memories.filter(visibleNotice);html=`<div class="info-box"><h3>То, что осталось с тобой</h3><p>Важные моменты хранятся здесь всю жизнь. Ограничение хроники в пять лет к воспоминаниям не применяется.</p></div>${memories.slice().reverse().map(m=>`<article class="section-card memory"><span class="eyebrow">${m.age} ЛЕТ</span><h3>${escape(m.title)}</h3><p>${escape(m.text)}</p></article>`).join('')||'<p class="helper">Впереди ещё много важных моментов.</p>'}`;}
if(section==='desires')html=desiresView(s,ui);if(section==='health')html=medicalView(s,ui);return tabs+html;}

function ownedHomesView(s,ui){const {money,escape,profile}=ui,econ=profile(s),owned=allHomes.filter(h=>s.city.owned.includes(h.id)),plots=ownedPlotRecords(s);if(!owned.length&&!plots.length)return '';const eligible=s.friends.filter(f=>f.status!=='deceased'&&f.bond>=60&&f.age>=16&&(!f.country||f.country===s.country));const action=(h,label,id,value='',disabled=false)=>`<button class="outline" data-home-action="${id}" data-home-id="${h.id}" data-value="${value}" ${available(s,id==='repair'&&value==='major'?1.5:id==='care'?.25:1)||disabled?'disabled':''}>${label}</button>`;return `<section id="ownedProperties" class="owned-properties"><h3 class="list-title">Моя недвижимость · ${owned.length+plots.length}</h3>${owned.map(h=>{const r=s.city.propertyRecords[h.id],condition=homeCondition(s,h);return `<article class="section-card owned-home" data-owned-home="${h.id}"><span class="eyebrow">${s.housing==='owned'&&s.city.residence===h.id?'ТВОЙ ДОМ':'В СОБСТВЕННОСТИ'}</span><h3>${escape(h.title)}</h3><button type="button" class="property-thumb" data-home-interior="${h.id}" aria-label="Посмотреть интерьер: ${escape(h.title)}">${homeArtwork(h,'owned',condition)}</button><p>${cityDistricts[h.district].name} · ${homeAddress(h)}</p><div class="button-row"><button type="button" class="outline" data-home-interior="${h.id}">Интерьер</button><button type="button" class="outline" data-map-home="${h.id}">На карте</button></div><div class="home-condition"><span>Состояние <b>${condition}/100</b></span><div class="track"><i style="width:${condition}%"></i></div></div><p>В собственности ${r.years} г. · комфорт ${propertyComfort(s,h)}/100<br>Продажа после расходов сделки: <b>${money(homeSalePrice(s,h,econ))}</b></p><label>Уход за жильём<select data-home-care="${h.id}" ${available(s,.25)?'disabled':''}>${Object.entries(homeCarePlans).map(([id,p])=>`<option value="${id}" ${r.care===id?'selected':''}>${p.name} · ${money(h.upkeep*p.factor*econ.cost)}/год</option>`).join('')}</select></label><p class="helper">Обычный уход: −2 состояния за год, тщательный: −0,5, экономия: −6. Износ снижает комфорт и цену продажи. При долгах состояние ухудшается быстрее.</p><div class="button-row">${action(h,'Косметический ремонт · '+money(repairQuote(s,h,'cosmetic',econ)),'repair','cosmetic',condition>=95||r.repairYear===s.age)}${action(h,'Капитальный ремонт · '+money(repairQuote(s,h,'major',econ)),'repair','major',condition>=95||r.repairYear===s.age)}</div><p class="helper">Косметический ремонт восстанавливает до 20 состояния, капитальный — до 60. Один ремонт объекта в год.</p><div class="button-row"><button class="outline" data-city="moveHome" data-value="${h.id}" ${available(s,.5)||s.housing==='owned'&&s.city.residence===h.id?'disabled':''}>Жить здесь</button><button class="outline" data-city="sellHome" data-value="${h.id}" ${available(s,.5)?'disabled':''}>Продать · ${money(homeSalePrice(s,h,econ))}</button></div><details class="home-party" id="party-${h.id}"><summary>Устроить домашнюю вечеринку</summary><p>Выбери до ${guestLimitText(homePartyCapacity(h))}. Угощение: 20 $ + 15 $ за гостя. Вечеринка укрепляет отношения, но немного изнашивает жильё.</p>${eligible.length?`<div class="party-guests">${eligible.map(f=>`<label class="party-guest-label"><input type="checkbox" class="party-guest" data-party-home="${h.id}" value="${f.id}" ${s.city.partyYear===s.age?'disabled':''}><span>${escape(f.name)}</span></label>`).join('')}</div>`:'<p class="helper">Пока нет друзей от 16 лет с близостью от 60. Сначала укрепи дружбу.</p>'}${action(h,s.city.partyYear===s.age?'Вечеринка уже была в этом году':'Позвать выбранных друзей','party','',!eligible.length||s.age<16||condition<25||s.city.partyYear===s.age)}</details></article>`;}).join('')}${ownedPlotsView(s,ui,plots)}</section>`;}

function wardrobeView(s,ui){const {money}=ui,wardrobeGender=ui.wardrobeGender||s.gender,category=Object.hasOwn(clothingCategories,ui.clothingFilter)?ui.clothingFilter:'all',owned=p=>s.shopping.wardrobe.includes(p.id),matches=(p,key)=>key==='all'||(key==='owned'?owned(p):clothingCategory(p)===key),items=clothingProducts.filter(p=>matches(p,category)&&styleAllowed(wardrobeGender,p.slot,p.value));
return `<div class="info-box"><span class="eyebrow">ТВОЙ СТИЛЬ</span><h3>Одежда и аксессуары</h3><div class="button-row"><button class="outline ${wardrobeGender==='male'?'active':''}" data-wardrobe-gender="male">Мужской раздел</button><button class="outline ${wardrobeGender==='female'?'active':''}" data-wardrobe-gender="female">Женский раздел</button></div><p>Выбирай фасоны для работы, прогулок и особых случаев. Покупку можно сразу надеть, а цвета изменить во «Внешности».</p><button class="outline" data-open-appearance="true">Открыть внешность</button></div><div class="wardrobe-filters"><label>Категория<select id="clothingCategory">${Object.entries(clothingCategories).map(([id,name])=>`<option value="${id}" ${category===id?'selected':''}>${name} · ${clothingProducts.filter(p=>matches(p,id)&&styleAllowed(wardrobeGender,p.slot,p.value)).length}</option>`).join('')}</select></label><span class="helper">У тебя ${s.shopping.wardrobe.length} ${countWord(s.shopping.wardrobe.length,['вещь','вещи','вещей'])}</span></div><div class="product-grid wardrobe-catalog">${items.map(p=>{const wearing=s.appearance[p.slot]===p.value,has=owned(p),preview=p.slot==='clothes'?clothingArtwork(p.value,s.appearance.clothingColor,s.appearance.accentColor):renderPortrait({...s,appearance:{...s.appearance,[p.slot]:p.value}}).replace('viewBox="0 0 200 220"','viewBox="32 0 136 190"');return `<article class="section-card product-card clothing-card" data-clothing-id="${p.id}"><div class="product-illustration clothing-preview" aria-hidden="true">${preview}</div><span class="listing-tag">${has?(wearing?'НАДЕТО':'В ГАРДЕРОБЕ'):clothingCategories[clothingCategory(p)].toUpperCase()}</span><h3>${p.name}</h3><b class="listing-price">${money(p.price)}</b><p>${p.description}</p><button class="outline" data-shopping="${has?'wear':'buyClothing'}" data-value="${p.id}" ${available(s,has?0:.25)||has&&wearing||!styleAllowed(s.gender,p.slot,p.value)?'disabled':''}>${has?(wearing?'Надето':'Надеть'):'Купить и надеть'}</button></article>`;}).join('')||'<p class="helper">В этой категории пока нет вещей.</p>'}</div>`;}

function shoppingView(s,section,ui){const {money,escape}=ui;const button=(label,id,value,disabled=false)=>`<button class="outline" data-shopping="${id}" data-value="${value}" ${available(s,['wear','computer'].includes(id)?0:id==='useElectronics'?.5:.25)||disabled?'disabled':''}>${label}</button>`;
if(section==='clothing')return wardrobeView(s,ui);
const owned=s.shopping.electronics;return `<div class="info-box"><span class="eyebrow">ТЕХНИКА ДЛЯ ЖИЗНИ</span><h3>Электроника</h3><p>Устройствами можно пользоваться для учёбы, творчества, общения и отдыха. Техника стареет, её можно ремонтировать и продавать.${computerReady(s)?'<br>Исправный домашний компьютер помогает учебным и IT-проектам.':''}</p></div>${owned.length?`<h3 class="list-title">Моя техника · ${owned.length}</h3>${owned.map(r=>{const p=electronicProducts.find(p=>p.id===r.id);return `<article class="section-card owned-electronics"><span class="listing-tag">${s.shopping.activeComputer===r.id?'ОСНОВНОЙ КОМПЬЮТЕР':'У ТЕБЯ'}</span><h3>${p.name}</h3><p>Состояние ${r.condition}/100 · используется ${r.years} г.<br>${p.description}</p><div class="button-row">${button(r.useYear===s.age?'Уже занимался в этом году':'Провести время','useElectronics',p.id,s.age<5||r.condition<30||r.useYear===s.age)}${p.category==='computer'?button('Для домашних проектов','computer',p.id,s.shopping.activeComputer===p.id||r.condition<30):''}${button('Ремонт · '+money(Math.max(15,Math.round(p.price*.12))),'repairElectronics',p.id,r.condition>=95||r.repairYear===s.age)}${button('Продать · '+money(p.price*.7*Math.max(.15,.83**r.years)*r.condition/100),'sellElectronics',p.id)}</div></article>`;}).join('')}`:''}<h3 class="list-title">Каталог электроники</h3><div class="product-grid">${electronicProducts.map(p=>`<article class="section-card product-card"><div class="product-illustration" aria-hidden="true">${deviceIcon(p.category)}</div><span class="listing-tag">${{phone:'СВЯЗЬ',computer:'КОМПЬЮТЕРЫ',creative:'ТВОРЧЕСТВО',leisure:'ОТДЫХ',home:'ДЛЯ ДОМА'}[p.category]}</span><h3>${p.name}</h3><b class="listing-price">${money(p.price)}</b><p>${p.description}</p>${button(owned.some(r=>r.id===p.id)?'Уже куплено':'Купить','buyElectronics',p.id,owned.some(r=>r.id===p.id))}</article>`).join('')}</div>`;}
function deviceIcon(category){return `<svg viewBox="0 0 160 100"><g fill="none" stroke="currentColor" stroke-width="4" stroke-linejoin="round">${category==='phone'?'<rect x="59" y="10" width="42" height="80" rx="8"/><path d="M73 18h14M74 80h12"/>':category==='computer'?'<rect x="32" y="14" width="96" height="60" rx="5"/><path d="M25 82h110M43 82l8-8m58 0 8 8"/>':category==='creative'?'<rect x="30" y="30" width="100" height="55" rx="8"/><circle cx="80" cy="57" r="18"/><path d="M53 30l7-14h32l7 14M111 43h8"/>':category==='home'?'<rect x="22" y="18" width="116" height="65" rx="5"/><path d="M67 90h26"/>':'<path d="M40 60V43a40 40 0 0 1 80 0v17"/><rect x="30" y="46" width="20" height="39" rx="8"/><rect x="110" y="46" width="20" height="39" rx="8"/>'}</g></svg>`;}

// Original SVG interiors. Geometry changes with the property type; finishes follow its price.
const interiorLevels=[
 {id:'budget',name:'Простая обстановка',limit:60000,wall:'#ded7c7',floor:'#a78b6a',fabric:'#9b846b',accent:'#746c54',description:'Недорогая мебель, простые покрытия и компактное хранение.'},
 {id:'standard',name:'Базовый комфорт',limit:160000,wall:'#e7e2d6',floor:'#b59975',fabric:'#759188',accent:'#9d7955',description:'Практичная мебель, светлая отделка и всё необходимое для быта.'},
 {id:'comfort',name:'Улучшенная отделка',limit:350000,wall:'#ece6dc',floor:'#b39674',fabric:'#718781',accent:'#a58a60',description:'Встроенное хранение, качественные материалы и продуманное освещение.'},
 {id:'premium',name:'Дизайнерский интерьер',limit:700000,wall:'#e9e3db',floor:'#c9baa3',fabric:'#68746f',accent:'#ab8854',description:'Авторская мебель, натуральный камень, паркет и многослойный свет.'},
 {id:'luxury',name:'Премиальная резиденция',limit:Infinity,wall:'#eee8df',floor:'#ddd5c7',fabric:'#86877b',accent:'#b39153',description:'Просторные зоны отдыха, панорамное остекление и дорогие натуральные материалы.'}
];
function homeInteriorSpec(h){const level=interiorLevels.find(l=>h.price<l.limit)||interiorLevels.at(-1),type=homeType(h);return {...level,type,layout:type==='apartment'&&h.style==='heritage'?'heritage':type,spacious:h.area>=95,description:level.description};}
const artEscape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const artCache=new Map();
function interiorWindow(key,{x=278,y=38,w=124,h=136,garden=false,panorama=false,arch=false}={}){
 const top=arch?`M${x} ${y+26}Q${x+w/2} ${y-28} ${x+w} ${y+26}V${y+h}H${x}Z`:`M${x} ${y}h${w}v${h}H${x}Z`,clip=key+'-window';
 return `<defs><clipPath id="${clip}"><path d="${top}"/></clipPath></defs><path d="${top}" fill="#65706a" stroke="#f5f0e5" stroke-width="7"/><g clip-path="url(#${clip})"><rect x="${x}" y="${y-10}" width="${w}" height="${h+12}" fill="url(#${key}-glass)"/>${garden?`<path d="M${x} ${y+h-22}q${w/4} -35 ${w/2} -7t${w/2} 3v40H${x}Z" fill="#8aa07a"/><g fill="#638269"><ellipse cx="${x+w*.2}" cy="${y+h-55}" rx="18" ry="36"/><ellipse cx="${x+w*.79}" cy="${y+h-48}" rx="26" ry="29"/></g><path d="M${x+w*.2} ${y+h-54}v52m${w*.59} -45v45" stroke="#7e7b5f" stroke-width="3"/>`:`<g fill="#94a9a5"><path d="M${x} ${y+h}v-37h22v-21h23v58m8 0v-85h24v85m9 0v-53h29v53m10 0v-103h23v103m9 0v-66h27v66m9 0v-43h35v43"/></g><g fill="#d9d9bc" opacity=".7">${Array.from({length:8},(_,i)=>`<rect x="${x+10+i*19}" y="${y+h-30-(i%3)*12}" width="4" height="7"/>`).join('')}</g>`}<path d="M${x+7} ${y+5}l${w*.6} ${h}h${w*.17}L${x+w*.23} ${y+5}Z" fill="#fff" opacity=".14"/></g><path d="M${x+w/2} ${y+3}v${h-4}${panorama?'':`m${-w/2} ${-h*.47}h${w}`}" fill="none" stroke="#eee9df" stroke-width="4"/>`;
}
function interiorSofa({x=75,y=140,w=164,color='#759188',premium=false}={}){return `<ellipse cx="${x+w/2}" cy="${y+79}" rx="${w*.57}" ry="10" fill="#3e3a32" opacity=".15"/><path d="M${x+6} ${y+42}V${y+8}q0-10 12-10h${w-36}q12 0 12 11v36Z" fill="${color}"/><rect x="${x}" y="${y+35}" width="${w}" height="35" rx="8" fill="${color}"/><rect x="${x-7}" y="${y+29}" width="18" height="43" rx="6" fill="${color}"/><rect x="${x+w-11}" y="${y+29}" width="18" height="43" rx="6" fill="${color}"/><path d="M${x+14} ${y+36}h${w-28}m${-(w-28)/2} 0v-32" stroke="#fffdf4" opacity=".2"/><path d="M${x+6} ${y+71}v9m${w-12} -9v9" stroke="#675e4b" stroke-width="4"/><path d="M${x+20} ${y+8}l25-3 5 29-27 1Z" fill="#ddd1b9"/><path d="M${x+w-48} ${y+8}l23 6-6 23-24-7Z" fill="${premium?'#a89a84':'#b2bda3'}"/>${premium?`<path d="M${x+59} ${y+36}l5-29 22 1 9 40-7 19-15-3-5-26" fill="#c8b99c" opacity=".8"/>`:''}`;}
function interiorTable(x,y,premium=false){return `<ellipse cx="${x}" cy="${y+26}" rx="47" ry="7" fill="#494338" opacity=".14"/><path d="M${x-28} ${y+3}l-4 28m61-28 5 25" stroke="#5d5549" stroke-width="4"/><ellipse cx="${x}" cy="${y}" rx="48" ry="11" fill="${premium?'#e5ddca':'#c5a57d'}" stroke="${premium?'#b4a78c':'#a18664'}"/><path d="M${x-18} ${y-5}h25v4h-25Z" fill="#73837b"/><ellipse cx="${x+17}" cy="${y-4}" rx="5" ry="3" fill="#f9f5e8"/>`;}
function interiorPlant(x,y,size=1){return `<g transform="translate(${x} ${y}) scale(${size})"><ellipse cy="4" rx="19" ry="5" fill="#463f31" opacity=".14"/><path d="M-16-24h32L11 3h-22Z" fill="#b49b7e"/><path d="M0-24v-58m0 31q-30-1-24-23 23 4 24 23m1-14q9-29 28-20 0 21-28 20m-2-10q-16-29-4-36 16 12 4 36" fill="#6f8868" stroke="#5d7659" stroke-width="2"/></g>`;}
function interiorBed(x,y,w=136,budget=false){return `<path d="M${x} ${y}h${w-18}l26 42H${x-5}Z" fill="${budget?'#8c7968':'#a18e73'}"/><rect x="${x}" y="${y-24}" width="${w-18}" height="29" rx="${budget?2:7}" fill="${budget?'#9b856c':'#b5a88f'}"/><path d="M${x+4} ${y+1}h${w-26}l21 30H${x-1}Z" fill="#ece5d4"/><path d="M${x+11} ${y+4}h35l5 12h-42Z" fill="#fcf8ed"/><path d="M${x+w-63} ${y+4}h31l8 12h-36Z" fill="#f6f0e3"/><path d="M${x+1} ${y+21}h${w+3}l12 17H${x-4}Z" fill="${budget?'#a2a28c':'#7e9692'}"/><path d="M${x-2} ${y+43}v9m${w+17} -9v9" stroke="#695e4d" stroke-width="4"/>`;}
